from lib import *
S = SS('x54')
steps = [
    step("Boot 默认的 Tomcat 参数(从 TomcatServerProperties 读出):threads.max=200、threads.min-spare=10、max-connections=8192、accept-count=100,connection-timeout 没设(null,由 Tomcat 自己的默认值决定)。排队有三层:最多 200 个线程在干活;连接数最多 8192 个;操作系统的等待队列 100 个。后面把这几个值调小,看每一层满了会怎样。", t=tl(S(1)), mark=lidx(S(1), 'threads.max=200'), done=lidx(S(1), 'threads.max=200'), b=bars([['threads.max', 200, '200'], ['threads.min-spare', 10, '10'], ['accept-count', 100, '100']], 200, done=[0, 1, 2]), kv=KV([['threads.max', '200'], ['max-connections', '8192'], ['accept-count', '100'], ['connection-timeout', '未设置(null)']], ['threads.max'])),
    step("线程池满了:threads.max 设为 2,同时发起 8 个请求,每个处理 1000 ms。请求全部成功,但总耗时成对出现:1054、1054、2061、2062、3065、3067、4071、4072 ms——每次只有两个在跑,其余排队等线程。TCP 连接建立几乎是 0~1 ms,说明排队发生在连接已经建好之后。压力期间另发一个只需要几毫秒的 /fast,等了 3770 ms 才返回(排在八个慢请求之后),此时服务端的 exec 线程数始终是 2。没有任何错误,只是变慢——慢请求把线程占满,快请求也跟着排队。", t=tl(S(2)), mark=lidx(S(2), '/fast'), done=lidx(S(2), '成功请求的总耗时', '建立 TCP 连接'), b=bars([['第 1 对请求耗时 ms', 1054, '1054'], ['第 4 对请求耗时 ms', 4072, '4072'], ['同时发的 /fast 耗时 ms', 3770, '3770(排队)']], 4072, done=[0, 1], mark=[2]), kv=KV([['threads.max=2', '每次只有 2 个请求在处理'], ['超出的请求', '连接建好,排队等线程,不报错'], ['快请求', '被慢请求拖慢,等了 3770 ms'], ['exec 线程数', '始终 2']], ['快请求'])),
    step("连接超过上限:threads.max=2,12 个请求同时发起(每个 1000 ms),max-connections 与 accept-count 的组合,每个组合连做 3 轮。accept-count=100:3 轮都是 12 个全部成功,最慢 6 秒左右。accept-count 调小之后出现失败:max-connections=4、accept-count=2,三轮成功数是 2、6、5,其余在连接阶段就被 ConnectionResetError(1 ms 内),也有发请求阶段的 BrokenPipeError;accept-count=5,成功 5、9、9;accept-count=8,成功 7、12、12;max-connections=100、accept-count=2,第 1 轮只成功 2 个,后两轮全部成功。失败的请求都在 1 ms 内就失败,不是超时;每轮的成功个数在波动,第一次冲击新启动的进程更容易失败。这是 macOS 本机回环的结果,Linux 上的表现(SYN 被丢弃后重试)这里没有验证。", t=tl(S(3)), mark=lidx(S(3), '成功\': 2', '成功\': 6', '成功\': 5'), done=lidx(S(3), 'accept-count=100:', '成功\': 12'), b=bars([['accept-count=2 第 1 轮成功数', 2, '2/12'], ['accept-count=5 第 2 轮成功数', 9, '9/12'], ['accept-count=8 第 2 轮成功数', 12, '12/12'], ['accept-count=100 每轮成功数', 12, '12/12']], 12, mark=[0, 1], done=[2, 3]), kv=KV([['accept-count 够大', '全部成功,只是排队更久'], ['accept-count 很小', '多余的连接被立即重置'], ['失败形态', '1 ms 内 ConnectionResetError,不是超时'], ['结果的稳定性', '每轮成功数在波动,macOS 上测得']], ['accept-count 很小'])),
    step("connection-timeout=1500ms 会不会把排队的请求踢掉?threads.max 设为 2,同时发起 8 个请求(每个 1000 ms):全部成功,总耗时 1052、1053、2056、2059、3064、3064、4070、4070 ms,最长的等了 4 秒,远超 1500 ms;/fast 同样排队 3764 ms。这个超时没有把排在队里等线程的请求踢掉。想限制「排队多久就放弃」,要在更外层(网关、客户端的读超时)或者应用层做,线程池本身的队列是不限时的。", t=tl(S(4)), mark=lidx(S(4), '成功请求的总耗时'), done=lidx(S(4), '8 个并发请求', '/fast'), b=bars([['connection-timeout 设定 ms', 1500, '1500'], ['最久排队的请求总耗时 ms', 4070, '4070(没被踢掉)'], ['失败请求数', 0, '0']], 4070, cur=[0], mark=[1], done=[2]), kv=KV([['connection-timeout=1500ms', '没有踢掉排队等线程的请求'], ['线程池队列', '不限时,只有客户端或网关能放弃'], ['最久的请求', '等了约 4 秒仍成功']], ['connection-timeout=1500ms'])),
]
A = mkartx('x54', 54, 'Spring,Tomcat,线程池,max-threads,accept-count,max-connections,真实验证,动画演示',
    '实测 Spring Boot 内嵌 Tomcat 线程池满了会怎样:默认 threads.max=200、max-connections=8192、accept-count=100;threads.max=2 时请求成对排队、不报错,一个几毫秒的 /fast 被拖到 3770 ms;accept-count 很小时,多余的连接在 1 ms 内被 ConnectionResetError(macOS 本机回环,成功个数每轮波动);connection-timeout 不会踢掉排队等线程的请求。',
    '线程池满了请求是报错还是排队?accept-count 和 max-connections 到底管什么?为什么慢接口会把快接口也拖慢?排队的请求会不会超时?这篇把 Tomcat 线程数、连接数和等待队列调小,用并发请求在本机回环上逐个测量(平台是 macOS,Linux 的表现没有验证)。',
    [('3770 ms', 'threads.max=2 时,一个只需几毫秒的 /fast 请求被八个慢请求拖到的耗时'), ('9 / 12', 'accept-count=5、max-connections=4 的第 2 轮,12 个同时发起的请求里成功的个数'), ('4070 ms', 'connection-timeout=1500ms 时,最久排队的请求仍然成功的总耗时')],
    [('默认值', '<p>200 个线程、8192 个连接、100 的等待队列。</p>'),
     ('线程满了', '<p>排队不报错,快请求也会被慢请求拖慢。</p>'),
     ('连接超过上限', '<p>accept-count 很小时,多余的连接被立即重置,每轮成功数波动。</p>'),
     ('排队不超时', '<p>connection-timeout 踢不掉排队等线程的请求,要在更外层限时。</p>')],
    steps,
    [ENV_X + '。用 Spring Boot 4.0.8 的 SpringApplication(spring-boot-starter-webmvc,内嵌 Tomcat 11.0.24 NIO);macOS 上本机回环 127.0.0.1,客户端用 Python 线程同时发起请求,连接与读超时 10 秒;默认值取自应用里注入的 TomcatServerProperties;第三节每个组合连做 3 轮,成功个数不稳定(第一次冲击新启动的进程更容易失败)',
     '没有验证:Linux 上 accept-count 溢出的表现(内核的 SYN 队列与 tcp_abort_on_overflow);max-connections 到达上限后 Tomcat 接受器停止接受连接的内部机制(只测了外部现象);虚拟线程下线程池的变化(见第 60 篇);Undertow、Jetty 的对应参数;keep-alive 空闲连接占用 max-connections 的情况;server.tomcat.threads.max 的动态调整;Actuator 的 tomcat.threads.busy 指标(见第 80 篇)'],
    '线程池满了')
